static inline uint64_t h264ring_get(const uint64_t *w, unsigned word, unsigned lsb, unsigned width)
{
    uint64_t v = w[word] >> lsb;
    return width >= 64 ? v : (v & ((1ULL << width) - 1));
}
#define H264RING_GET(w, F) h264ring_get((w), H264RING_##F##_W, H264RING_##F##_LSB, H264RING_##F##_WIDTH)

